// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        address(c).call{value: 1 ether}("");

        address recipient = address(0x123);
        uint256 initialBalance = address(recipient).balance;

        vm.prank(address(this));
        c.withdrawAll(recipient);

        assertEq(address(recipient).balance - initialBalance, 1 ether);
    }
}
